#!/usr/bin/env python3
"""Gzip local web assets and embed them in a deterministic C++ header."""

import argparse
import gzip
from pathlib import Path


ASSETS = {
    "index.html": ("/", "text/html; charset=utf-8"),
    "style.css": ("/style.css", "text/css; charset=utf-8"),
    "app.js": ("/app.js", "application/javascript; charset=utf-8"),
    "manifest.webmanifest": ("/manifest.webmanifest", "application/manifest+json"),
    "icon.svg": ("/icon.svg", "image/svg+xml"),
}


def build(source: Path, output: Path) -> None:
    lines = [
        "// Generated by scripts/web-to-header.py. Do not edit by hand.",
        "#pragma once",
        "#include <Arduino.h>",
        "struct EmbeddedWebFile { const char* path; const char* mime; const uint8_t* data; size_t size; };",
    ]
    entries = []
    total_original = 0
    total_gzip = 0
    for index, (name, (path, mime)) in enumerate(ASSETS.items()):
        raw = (source / name).read_bytes()
        compressed = gzip.compress(raw, compresslevel=9, mtime=0)
        symbol = f"web_asset_{index}"
        lines.append(f"static const uint8_t {symbol}[] PROGMEM = {{")
        for offset in range(0, len(compressed), 16):
            chunk = compressed[offset : offset + 16]
            lines.append("  " + ", ".join(f"0x{byte:02x}" for byte in chunk) + ",")
        lines.append("};")
        entries.append(f'  {{"{path}", "{mime}", {symbol}, sizeof({symbol})}},')
        total_original += len(raw)
        total_gzip += len(compressed)
        print(f"{name}: {len(raw)} -> {len(compressed)} bytes")
    lines.append("static const EmbeddedWebFile embeddedWebFiles[] = {")
    lines.extend(entries)
    lines.append("};")
    lines.append("static constexpr size_t embeddedWebFileCount = sizeof(embeddedWebFiles) / sizeof(embeddedWebFiles[0]);")
    content = "\n".join(lines) + "\n"
    output.parent.mkdir(parents=True, exist_ok=True)
    if not output.exists() or output.read_text() != content:
        output.write_text(content)
    print(f"Web assets: {total_original} -> {total_gzip} bytes ({100 * (1 - total_gzip / total_original):.1f}% smaller)")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    parser.add_argument("-o", "--output", type=Path, required=True)
    args = parser.parse_args()
    build(args.source, args.output)
